    // Decreases: The length of dst (and src, mask) is non-negative.
    // Invariant: At the start of each iteration, result has length i,
    //            where i is the current index in the loop.

    assert!(dst.len() == src.len() && dst.len() == mask.len()); // Precondition

    let mut result = Vec::with_capacity(dst.len());

    // Loop invariant: result has length i and contains the correct elements
